alter table public.casos add column if not exists investigado_cip text; create index if not exists casos_investigado_cip_idx on public.casos (investigado_cip); drop policy if exists "ve casos propios o es admin" on public.casos; create policy "ve casos propios, investigado o es admin" on public.casos for select to authenticated using (public.es_admin() or oficial_constato_cip = public.cip_actual() or investigado_cip = public.cip_actual()); create table if not exists public.suscripciones_movil (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, cip text not null, endpoint text not null unique, p256dh text not null, auth text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.suscripciones_movil enable row level security; drop policy if exists "usuario ve sus alertas móviles" on public.suscripciones_movil; drop policy if exists "usuario registra sus alertas móviles" on public.suscripciones_movil; drop policy if exists "usuario actualiza sus alertas móviles" on public.suscripciones_movil; drop policy if exists "usuario elimina sus alertas móviles" on public.suscripciones_movil; create policy "usuario ve sus alertas móviles" on public.suscripciones_movil for select to authenticated using (user_id = auth.uid()); create policy "usuario registra sus alertas móviles" on public.suscripciones_movil for insert to authenticated with check (user_id = auth.uid() and cip = public.cip_actual()); create policy "usuario actualiza sus alertas móviles" on public.suscripciones_movil for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid() and cip = public.cip_actual()); create policy "usuario elimina sus alertas móviles" on public.suscripciones_movil for delete to authenticated using (user_id = auth.uid()); drop trigger if exists suscripciones_movil_set_updated_at on public.suscripciones_movil; create trigger suscripciones_movil_set_updated_at before update on public.suscripciones_movil for each row execute function public.set_updated_at();
